import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.B_9sDCyK.js";const p=JSON.parse('{"title":"What a result means","description":"","frontmatter":{"title":"What a result means"},"headers":[],"relativePath":"concepts/results-and-trust.md","filePath":"concepts/results-and-trust.md"}'),s={name:"concepts/results-and-trust.md"};function d(c,e,n,i,h,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-a-result-means" tabindex="-1">What a result means <a class="header-anchor" href="#what-a-result-means" aria-label="Permalink to &quot;What a result means&quot;">​</a></h1><p>Most mistakes with a payment API come from reading one flag as another. This page is the short version of what each signal in <code>paystack_sdk</code> does and does not tell you.</p><h2 id="success-is-not-the-payment-worked" tabindex="-1"><code>success?</code> is not &quot;the payment worked&quot; <a class="header-anchor" href="#success-is-not-the-payment-worked" aria-label="Permalink to &quot;`success?` is not &quot;the payment worked&quot;&quot;">​</a></h2><p><code>response.success?</code> is true when Paystack accepted the call and answered with a success HTTP status. <code>transactions.verify</code> succeeds for any reference Paystack knows, paid or not. The outcome of the payment is in <code>data.status</code>.</p><table tabindex="0"><thead><tr><th>You want to know</th><th>Look at</th><th>Not at</th></tr></thead><tbody><tr><td>Was the call accepted?</td><td><code>success?</code></td><td></td></tr><tr><td>Was the customer charged the right amount?</td><td><code>paid?(amount:, currency:)</code></td><td><code>success?</code></td></tr><tr><td>What state is the transaction in?</td><td><code>status?(:success)</code>, or <code>data.status</code></td><td>the HTTP status</td></tr><tr><td>Why did a charge stop?</td><td><code>data.status</code> and <code>gateway_response</code></td><td><code>success?</code></td></tr></tbody></table><h2 id="three-kinds-of-failure-three-behaviours" tabindex="-1">Three kinds of failure, three behaviours <a class="header-anchor" href="#three-kinds-of-failure-three-behaviours" aria-label="Permalink to &quot;Three kinds of failure, three behaviours&quot;">​</a></h2><ul><li><strong>A call that cannot be valid</strong> (a malformed email, an amount of <code>50.0</code>) raises <code>PaystackSdk::InvalidValueError</code> before anything is sent.</li><li><strong>A 400 or 404 from Paystack</strong> comes back as a <code>Response</code> with <code>success?</code> false and an <code>error_message</code>. It does not raise.</li><li><strong>A bad key, a rate limit or a server error</strong> (401, 429, 5xx) raises, so it cannot be mistaken for a result.</li></ul><h2 id="trust-your-own-record-not-the-browser" tabindex="-1">Trust your own record, not the browser <a class="header-anchor" href="#trust-your-own-record-not-the-browser" aria-label="Permalink to &quot;Trust your own record, not the browser&quot;">​</a></h2><p>Verify by <code>reference</code>, check the amount and currency with <code>paid?</code>, and compare the customer email before giving value. A redirect to your <code>callback_url</code> and a webhook body are both prompts to check, not proof.</p><h2 id="retries-are-conservative-on-purpose" tabindex="-1">Retries are conservative on purpose <a class="header-anchor" href="#retries-are-conservative-on-purpose" aria-label="Permalink to &quot;Retries are conservative on purpose&quot;">​</a></h2><p>Reads retry on network errors and on 429, 502, 503 and 504. Writes retry only on 429, and never after a timeout, because a write that timed out may have succeeded. Retrying it could charge a customer twice.</p><p>See the <a href="/paystack_sdk/latest/reference/response">Response reference</a>, <a href="/paystack_sdk/latest/reference/errors">Errors</a> and the <a href="/paystack_sdk/latest/skills/paystack-sdk-money-safety">money-safety skill</a>.</p>',12)])])}const m=t(s,[["render",d]]);export{p as __pageData,m as default};
